// Package keys ports the explicit placeholder-key setup from the Python
// reference (compatibility.py). It manages the two local placeholder keys that
// NSP Box writes into a prod.keys_autogenerated file for unsigned plaintext
// emulator repacks; it never handles retail keys.
package keys

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

// Names of the two placeholder keys this package manages.
const (
	HeaderKey               = "header_key"
	KeyAreaKeyApplication00 = "key_area_key_application_00"
)

// Values of the two placeholder keys (lowercase hex digests). These are local
// placeholders for unsigned plaintext repacks; they cannot decrypt retail
// content. Mirrors compatibility.PLACEHOLDERS.
const (
	HeaderKeyValue               = "489973ffb094480274e688c24c44e904ac52cf9fdc230cfaedf5ba8a971c958a" // sha256(b"local-plaintext-xci-header-placeholder")
	KeyAreaKeyApplication00Value = "737e30fde49335ee318bd36d2e084367"                                 // md5(b"local-plaintext-xci-area-placeholder")
)

var (
	placeholderOrder = []string{HeaderKey, KeyAreaKeyApplication00}
	placeholders     = map[string]string{
		HeaderKey:               HeaderKeyValue,
		KeyAreaKeyApplication00: KeyAreaKeyApplication00Value,
	}
	validValue = map[string]*regexp.Regexp{
		HeaderKey:               regexp.MustCompile(fmt.Sprintf(`[0-9a-fA-F]{%d}`, len(HeaderKeyValue))),
		KeyAreaKeyApplication00: regexp.MustCompile(fmt.Sprintf(`[0-9a-fA-F]{%d}`, len(KeyAreaKeyApplication00Value))),
	}
)

// PlaceholderText renders the placeholder key block. names == nil selects every
// placeholder in canonical order; otherwise the given names are written in the
// given order.
func PlaceholderText(names []string) string {
	order := names
	if order == nil {
		order = placeholderOrder
	}
	var b strings.Builder
	b.WriteString("# Local placeholders for unsigned plaintext repacks; NOT Nintendo keys.\n")
	b.WriteString("# Cannot decrypt retail content. Keep real keys in prod.keys.\n")
	for _, name := range order {
		b.WriteString(name)
		b.WriteString(" = ")
		b.WriteString(placeholders[name])
		b.WriteString("\n")
	}
	return b.String()
}

// Status reports whether the key directory is ready (all placeholders present
// and valid) and, when it is not, which keys are missing or invalid.
type Status struct {
	Ready   bool
	Missing []string
	Invalid []string
}

// Inspect reads prod.keys_autogenerated then prod.keys and reports the
// placeholder-key state without exposing any existing key values.
func Inspect(directory string) (Status, error) {
	effective := make(map[string]string)
	var order []string
	seen := make(map[string]bool)

	for _, filename := range []string{"prod.keys_autogenerated", "prod.keys"} {
		path := filepath.Join(directory, filename)
		fi, err := os.Lstat(path)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return Status{}, err
		}
		if fi.Mode()&os.ModeSymlink != 0 {
			return Status{}, errors.New("Choose a real emulator keys folder, without linked key files.")
		}
		if fi.Size() > 8*1024*1024 {
			return Status{}, errors.New("Key configuration file is unexpectedly large.")
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return Status{}, err
		}
		text := strings.TrimPrefix(string(data), "\ufeff")
		text = strings.ReplaceAll(text, "\r\n", "\n")
		text = strings.ReplaceAll(text, "\r", "\n")
		for _, line := range strings.Split(text, "\n") {
			if strings.HasPrefix(strings.TrimSpace(line), "#") || !strings.Contains(line, "=") {
				continue
			}
			parts := strings.SplitN(line, "=", 2)
			name := strings.ToLower(strings.TrimSpace(parts[0]))
			if _, ok := placeholders[name]; !ok {
				continue
			}
			if !seen[name] {
				seen[name] = true
				order = append(order, name)
			}
			effective[name] = strings.TrimSpace(parts[1])
		}
	}

	var missing []string
	for _, k := range placeholderOrder {
		if _, ok := effective[k]; !ok {
			missing = append(missing, k)
		}
	}
	var invalid []string
	for _, k := range order {
		if !validValue[k].MatchString(effective[k]) {
			invalid = append(invalid, k)
		}
	}
	return Status{Ready: len(missing) == 0 && len(invalid) == 0, Missing: missing, Invalid: invalid}, nil
}

// Result reports the outcome of Install, including which placeholders were
// added and the backup file created (empty when none).
type Result struct {
	Status
	Added  []string
	Backup string
}

// Install ensures the two placeholder keys are present in
// prod.keys_autogenerated, preserving any existing entries. It never overwrites
// an existing file in place: a fresh file is created exclusively, and an
// existing one is backed up then atomically replaced.
func Install(directory string) (Result, error) {
	abs, err := filepath.Abs(directory)
	if err != nil {
		return Result{}, err
	}
	if err := os.MkdirAll(abs, 0o777); err != nil {
		return Result{}, err
	}
	resolved, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return Result{}, err
	}

	status, err := Inspect(resolved)
	if err != nil {
		return Result{}, err
	}
	if len(status.Invalid) > 0 {
		return Result{}, fmt.Errorf("Existing entries need manual correction: %s", strings.Join(status.Invalid, ", "))
	}
	if status.Ready {
		return Result{Status: status, Added: []string{}, Backup: ""}, nil
	}

	target := filepath.Join(resolved, "prod.keys_autogenerated")
	before, err := os.ReadFile(target)
	exists := err == nil
	if err != nil && !os.IsNotExist(err) {
		return Result{}, err
	}

	addition := []byte(PlaceholderText(status.Missing))
	var content []byte
	if exists {
		content = append(content, before...)
		if !bytes.HasSuffix(before, []byte("\n")) {
			content = append(content, '\n')
		}
	}
	content = append(content, addition...)

	backup := ""
	if !exists {
		f, err := os.OpenFile(target, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
		if err != nil {
			return Result{}, err
		}
		if _, err := f.Write(content); err != nil {
			f.Close()
			return Result{}, err
		}
		if err := f.Sync(); err != nil {
			f.Close()
			return Result{}, err
		}
		if err := f.Close(); err != nil {
			return Result{}, err
		}
	} else {
		now := time.Now()
		ts := now.Format("20060102-150405") + "-" + fmt.Sprintf("%06d", now.Nanosecond()/1000)
		backupPath := filepath.Join(resolved, "prod.keys_autogenerated.packager-backup-"+ts)

		bf, err := os.OpenFile(backupPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
		if err != nil {
			return Result{}, err
		}
		if _, err := bf.Write(before); err != nil {
			bf.Close()
			return Result{}, err
		}
		if err := bf.Close(); err != nil {
			return Result{}, err
		}

		tf, err := os.CreateTemp(resolved, ".packager-*.tmp")
		if err != nil {
			return Result{}, err
		}
		temp := tf.Name()
		cleanup := func() { os.Remove(temp) }
		if _, err := tf.Write(content); err != nil {
			tf.Close()
			cleanup()
			return Result{}, err
		}
		if err := tf.Sync(); err != nil {
			tf.Close()
			cleanup()
			return Result{}, err
		}
		if err := tf.Close(); err != nil {
			cleanup()
			return Result{}, err
		}

		current, err := os.ReadFile(target)
		if err != nil {
			cleanup()
			return Result{}, err
		}
		if !bytes.Equal(current, before) {
			cleanup()
			return Result{}, errors.New("Key configuration changed during setup. Try again with the emulator closed.")
		}
		if err := os.Rename(temp, target); err != nil {
			cleanup()
			return Result{}, err
		}
		backup = backupPath
	}

	final, err := Inspect(resolved)
	if err != nil {
		return Result{}, err
	}
	return Result{Status: final, Added: append([]string(nil), status.Missing...), Backup: backup}, nil
}
